def run(case, planner, state_path, max_attempts=3, stop_after=None):
    if case not in CASES or not 1 <= max_attempts <= 3:
        raise ValueError('Use a registered case and 1–3 attempts')
    config = CASES[case]
    fixture = ROOT / 'fixtures' / config['folder']
    hashes = snapshot(fixture)
    source = (fixture / 'calculator.py').read_text(encoding='utf-8')
    if source.count(config['needle']) != 1:
        raise ValueError('Ambiguous repair location')
    state_path = Path(state_path)
    binding = {'case': case, 'fixture_sha256': hashes,
               'planner': planner.identity, 'max_attempts': max_attempts,
               'verifier_sha256': {name: hashlib.sha256((ROOT / name).read_bytes()).hexdigest()
                   for name in ('resumable_agent.py', 'verified_workflow.py', 'repair_agent.py')},
               'case_spec_sha256': hashlib.sha256(json.dumps(config, sort_keys=True).encode()).hexdigest()}
    if state_path.exists():
        state = json.loads(state_path.read_text(encoding='utf-8'))
        if state.get('binding') != binding or state.get('schema_version') != 2:
            raise ValueError('Resume refused: fixture, verifier, planner, budget or schema changed')
        if state['verdict'] == 'VERIFIED_PASS':
            try:
                revalidation = evaluate_expression(fixture, source, config, hashes, state.get('accepted_expression'))
            except (ValueError, SyntaxError, TypeError) as exc:
                raise ValueError('Checkpoint revalidation rejected the saved expression') from exc
            if revalidation['status'] != 'VERIFIED_PASS':
                raise ValueError('Checkpoint revalidation failed independent acceptance tests')
            state['resume_revalidation'] = revalidation
            state['events'].append('completed_checkpoint_independently_revalidated')
            save_atomic(state_path, state)
            return state
        if state['verdict'] in {'VERIFIED_FAIL', 'ALREADY_PASSING'}:
            if state['verdict'] == 'ALREADY_PASSING':
                with tempfile.TemporaryDirectory(prefix='proof-baseline-recheck-') as tmp:
                    folder = Path(tmp) / 'fixture'
                    shutil.copytree(fixture, folder, ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
                    revalidation = run_tests(folder)
                if not revalidation['passed']:
                    raise ValueError('Checkpoint revalidation failed: baseline is not passing')
            return state
        if state['verdict'] != 'RUNNING' or len(state['attempts']) > max_attempts:
            raise ValueError('Invalid resume state')
    else:
        with tempfile.TemporaryDirectory(prefix='proof-baseline-') as tmp:
            folder = Path(tmp) / 'fixture'
            shutil.copytree(fixture, folder, ignore=shutil.ignore_patterns('__pycache__', '*.pyc'))
            baseline = run_tests(folder)
        state = {'schema_version': 2, 'binding': binding, 'verdict': 'RUNNING',
                 'baseline': baseline, 'attempts': [], 'events': ['baseline_recorded']}
        if baseline['timed_out']:
            state['verdict'] = 'VERIFIED_FAIL'
            state['failure_reason'] = 'Baseline infrastructure timeout; defect not established'
        elif baseline['passed']:
            state['verdict'] = 'ALREADY_PASSING'
        save_atomic(state_path, state)
        if state['verdict'] != 'RUNNING':
            return state
    while len(state['attempts']) < max_attempts:
        if snapshot(fixture) != hashes:
            raise ValueError('Fixture changed during run')
        context = {'case': case, 'requirement': config['requirement'], 'source': source,
                   'allowed_variables': config['variables'], 'baseline': state['baseline'],
                   'attempts': state['attempts']}
        # A provider failure preserves state; resume does not replay verified attempts.
        proposal = planner.propose(context)
        attempt = {'number': len(state['attempts']) + 1, 'proposal': proposal}
        expression = proposal.get('expression')
        try:
            validate_expression(expression, set(config['variables']))
        except (ValueError, SyntaxError, TypeError) as exc:
            attempt.update(status='REJECTED', reason=str(exc))
        else:
            attempt.update(evaluate_expression(fixture, source, config, hashes, expression))
        state['attempts'].append(attempt)
        state['events'].append('attempt_' + str(attempt['number']) + '_' + attempt['status'])
        if attempt['status'] == 'VERIFIED_PASS':
            state['verdict'] = 'VERIFIED_PASS'
            state['accepted_expression'] = expression
        elif len(state['attempts']) >= max_attempts:
            state['verdict'] = 'VERIFIED_FAIL'
        state['original_unchanged'] = snapshot(fixture) == hashes
        save_atomic(state_path, state)
        if state['verdict'] != 'RUNNING':
            break
        if stop_after is not None and len(state['attempts']) >= stop_after:
            raise InterruptedRun('Checkpoint saved; rerun the same command without --stop-after to resume')
    return state

def validate_expression(expression, variables=None):
    if not isinstance(expression, str) or len(expression) > 240:
        raise ValueError('Candidate must be a short arithmetic expression')
    node = ast.parse(expression, mode='eval')
    allowed = (ast.Expression, ast.BinOp, ast.Add, ast.Sub, ast.Mult, ast.Div,
               ast.Name, ast.Load, ast.Constant)
    for item in ast.walk(node):
        if not isinstance(item, allowed):
            raise ValueError('Candidate contains unsupported syntax')
        if isinstance(item, ast.Name) and item.id not in (variables or {'subtotal', 'discount'}):
            raise ValueError('Candidate uses an unknown variable')
        if isinstance(item, ast.Constant) and type(item.value) not in (int, float):
            raise ValueError('Candidate contains a nonnumeric literal')
    return expression


@trace('AGENT', 'verify_repair_candidates')
def verify_candidates(fixture, candidates, output):
    fixture = Path(fixture).resolve()
    source = fixture / 'calculator.py'
    tests = fixture / 'tests'
    frozen = {str(p.relative_to(tests)): digest(p) for p in tests.rglob('*.py')}
    if not frozen:
        raise ValueError('Independent acceptance tests are required')
    original = source.read_text(encoding='utf-8')
    needle = '(subtotal - discount) - discount'
    if original.count(needle) != 1:
        raise ValueError('Unsupported fixture; expected one repair location')
    report = {'schema_version': 1, 'verdict': 'VERIFIED_FAIL',
              'planner': 'supplied_candidates', 'tests_sha256': frozen,
              'source_before_sha256': digest(source), 'attempts': []}
    with tempfile.TemporaryDirectory(prefix='proofagent-verify-') as tmp:
        baseline_dir = Path(tmp) / 'baseline'
        shutil.copytree(fixture, baseline_dir)
        report['baseline'] = run_tests(baseline_dir)
        if report['baseline']['passed']:
            report['verdict'] = 'ALREADY_PASSING'
        else:
            for index, expression in enumerate(candidates[:3], 1):
                attempt = {'number': index, 'expression': expression}
                report['attempts'].append(attempt)
                try:
                    validate_expression(expression)
                except (ValueError, SyntaxError) as exc:
                    attempt.update(status='REJECTED', reason=str(exc))
                    continue
                candidate_dir = Path(tmp) / ('candidate-' + str(index))
                shutil.copytree(fixture, candidate_dir)
                patched = candidate_dir / 'calculator.py'
                patched.write_text(original.replace(needle, expression, 1), encoding='utf-8')
                attempt['verification'] = run_tests(candidate_dir)
                observed = {str(p.relative_to(candidate_dir / 'tests')): digest(p)
                            for p in (candidate_dir / 'tests').rglob('*.py')}
                attempt['tests_unchanged'] = observed == frozen
                attempt['source_after_sha256'] = digest(patched)
                passed = attempt['verification']['passed'] and attempt['tests_unchanged']
                attempt['status'] = 'VERIFIED_PASS' if passed else 'VERIFIED_FAIL'
                if passed:
                    report['verdict'] = 'VERIFIED_PASS'
                    report['accepted_expression'] = expression
                    break
    report['original_unchanged'] = digest(source) == report['source_before_sha256']
    target = Path(output)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    return report
